using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string executorName = args["userName"].ToString();
        bool isModerator = bool.Parse(args["isModerator"].ToString());
        bool isBroadcaster = bool.Parse(args["isBroadcaster"].ToString());

        // Check permissions
        if (!isModerator && !isBroadcaster) {
            CPH.SendMessage($"@{executorName}, this command is only available to moderators.");
            return false;
        }

        string inputText = args["rawInput"].ToString();

        // Parse input: !giveggs @username amount
        if (string.IsNullOrEmpty(inputText)) {
            CPH.SendMessage($"@{executorName}, usage: !giveggs @username [amount]. Example: !giveggs @user 500");
            return false;
        }

        string[] parts = inputText.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length < 2) {
            CPH.SendMessage($"@{executorName}, usage: !giveggs @username [amount]. Example: !giveggs @user 500");
            return false;
        }

        string targetUser = parts[0].TrimStart('@');
        int amount;

        if (!int.TryParse(parts[1], out amount) || amount < 1) {
            CPH.SendMessage($"@{executorName}, please specify a valid amount (minimum 1).");
            return false;
        }

        // Get target user ID
        var userInfo = CPH.TwitchGetUser(targetUser);
        if (userInfo == null) {
            CPH.SendMessage($"@{executorName}, user @{targetUser} not found.");
            return false;
        }

        string targetUserId = userInfo.UserId;
        string targetUserName = userInfo.UserLogin;

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        JObject data;
        if (File.Exists(dataPath)) {
            string jsonData = File.ReadAllText(dataPath);
            data = JObject.Parse(jsonData);
        } else {
            data = new JObject();
            data["users"] = new JObject();
        }

        // Initialize user if needed
        if (data["users"] == null) data["users"] = new JObject();
        if (data["users"][targetUserId] == null) {
            data["users"][targetUserId] = new JObject();
            data["users"][targetUserId]["eggs"] = 0;
            data["users"][targetUserId]["d20Tokens"] = 0;
            data["users"][targetUserId]["rrTokens"] = 0;
        }

        // Grant eggs
        int currentEggs = (int)(data["users"][targetUserId]["eggs"] ?? 0);
        data["users"][targetUserId]["eggs"] = currentEggs + amount;

        File.WriteAllText(dataPath, data.ToString());

        CPH.SendMessage($"🥚 @{targetUserName} has been granted {amount} eggs by @{executorName}! New total: {currentEggs + amount} eggs.");

        return true;
    }
}
